#ifndef SERVO_HW_TEST_H
#define SERVO_HW_TEST_H

#include <stdint.h>

/* Standalone F407 test: PB6=TIM4_CH1, PB7=TIM4_CH2, AF2, 50 Hz.
 * PWM edges are generated by hardware. Update IRQ only counts 20 ms frames.
 * This driver must not run together with servo_port.c on the same timer. */
void ServoHwTest_Init(void);
void ServoHwTest_SetPulseUs(uint8_t channel, uint16_t pulse_us);
void ServoHwTest_Task(void);

/* Watch: frames increases at 50 Hz. Phase 0=initial hold, 1=servo1 open,
 * 2=servo1 home, 3=servo2 open, 4=servo2 home. */
extern volatile uint32_t g_servo_test_frames;
extern volatile uint32_t g_servo_test_phase;
extern volatile uint16_t g_servo_test_us[2];

#endif
